package com.example.domain.model.i18n

internal object DuaZh1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("醒来时的祈祷词", "一切赞颂全归真主，他使我们在死亡（睡眠）之后复活，我们终将归于他。", "醒来后立即诵读，以感谢真主。", "先知穆罕默德（愿主福安之）醒来时常诵读此词——以感恩和铭记后世开始新的一天。"),
        "dua_leaving_home" to DuaText("出门时的祈祷词", "奉真主之名，我只信托真主，一切能力与力量只归真主所有。", "出门时诵读，祈求真主的保护。", "有人会对他说：你已获得引导、供给和保护，恶魔便远离了他。"),
        "dua_anxiety_distress" to DuaText("消除忧愁与悲伤的祈祷词", "主啊！我求你庇护我免遭忧愁与悲伤、无能与懒惰、吝啬与怯懦、债务的重压与他人的欺压。", "在忧愁、悲伤、债务缠身或精神困扰时诵读。", "先知（愿主福安之）常诵读此词，以求庇护免遭忧愁、懒惰与债务。"),
        "dua_sayyidul_istighfar" to DuaText("求恕词之首", "主啊！你是我的主，除你之外绝无应受崇拜的。你创造了我，我是你的仆人。我尽力遵守与你的约定和承诺。我求你庇护我免遭我所做恶行的祸害。我承认你赐予我的恩典，也承认我的罪过，求你饶恕我，因为除你之外没有人能饶恕罪过。", "早晚诵读——先知（愿主福安之）所教导的最优美的忏悔词。", "谁在傍晚坚信地诵读并在当晚去世，他将进入天堂；早晨诵读亦有同样的美德。"),
        "dua_parents" to DuaText("为父母祈祷的祈祷词", "我的主啊！求你怜悯他们，就像他们在我年幼时抚养我一样。", "《古兰经》中为报答父母养育之恩而设的祈祷词。", "真主在《古兰经》中亲自命令这段为父母祈祷的经文。"),
        "dua_entering_mosque" to DuaText("进入清真寺时的祈祷词", "主啊！求你为我打开你慈悯的大门。", "进入清真寺时先迈右脚并诵读。", "先知（愿主福安之）教导进入清真寺时诵读此词。"),
        "dua_morning_asbahna" to DuaText("晨间赞辞", "我们已进入清晨，今晨的主权只归真主所有。一切赞颂全归真主。除真主外绝无应受崇拜的，他是独一的，没有伙伴。主权归他，赞颂归他，他对万事全能。", "在清晨诵读的圣行祈祷词。", "以承认真主的主权和独一性开始新的一天。"),
        "dua_evening_amsayna" to DuaText("晚间赞辞", "我们已进入黄昏，今晚的主权只归真主所有。一切赞颂全归真主。除真主外绝无应受崇拜的，他是独一的，没有伙伴。主权归他，赞颂归他，他对万事全能。", "在傍晚诵读的圣行祈祷词。", "以承认真主的主权和独一性开始夜晚。"),
        "dua_bismillah_la_yadurru" to DuaText("免遭一切伤害的祈祷词", "奉真主之名，奉他之名，天地间没有任何东西能造成伤害；他是全聪的、全知的。", "每天早晚各诵读三遍。", "谁每天早晚诵读三遍，任何东西都不会伤害他。"),
        "dua_raditu_billahi" to DuaText("喜悦真主为主", "我喜悦真主为我的主，伊斯兰为我的宗教，穆罕默德（愿主福安之）为我的先知。", "每天早晚各诵读三遍。", "真主必使他在末日感到喜悦，这已成为真主对他的应许。"),
        "dua_hasbiyallah" to DuaText("真主已使我足够", "真主已使我足够，除他外绝无应受崇拜的；我只信托他，他是伟大宝座之主。", "每天早晚各诵读七遍。", "《古兰经》中的经文；真主足以使人免除今世与后世的忧虑。"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("赞主超绝，万赞归主", "赞主超绝，万赞归主。", "每天诵读一百遍。", "谁每天诵读一百遍，他的罪过即便如海洋的泡沫那样多也会被赦免。"),
        "dua_tahleel_100" to DuaText("除真主外绝无应受崇拜的（百遍）", "除真主外绝无应受崇拜的，他是独一的，没有伙伴。主权归他，赞颂归他，他对万事全能。", "每天诵读一百遍有巨大的美德。", "相当于释放十名奴隶的赏赐，记下一百件善功，抹去一百件罪过，并在当晚得以免遭恶魔的侵扰直至傍晚。"),
        "dua_leaving_mosque" to DuaText("离开清真寺时的祈祷词", "主啊！我向你祈求你的恩惠。", "离开清真寺时先迈左脚并诵读。", "离开清真寺时向真主祈求恩惠与给养。"),
        "dua_after_adhan" to DuaText("宣礼后的祈祷词", "主啊！这完美的召唤和即将举行的拜功之主啊，求你赐予穆罕默德（愿主福安之）瓦西拉与美德，让他登上你所应许他的受赞美的地位。", "宣礼结束后诵读。", "谁诵读此词，先知（愿主福安之）在末日必为他说情。"),
        "dua_after_salah_istighfar" to DuaText("主命拜后的祈祷词", "我向真主求恕（三遍）。主啊！你是清安，安宁从你而来，你是吉祥的，尊严与荣耀之主啊！", "道安后立即诵读。", "先知（愿主福安之）在每次主命拜后都诵读此词。"),
        "dua_after_salah_help_dhikr" to DuaText("求助于纪念真主", "主啊！求你帮助我纪念你、感谢你，并以最好的方式敬拜你。", "每次礼拜后诵读——先知（愿主福安之）曾嘱咐穆阿兹（愿主喜悦之）如此诵读。", "先知（愿主福安之）的特别嘱托——敬拜中的美善与恒常。"),
        "dua_ayatul_kursi" to DuaText("礼拜后诵读的宝座经文", "真主，除他外绝无应受崇拜的；他是永生不灭的，是维护万物的。瞌睡不能侵犯他，睡眠不能克服他。天地万物都是他的。除非他许可，谁能在他那里替人说情呢？他知道众生前前后后的事情。除他所启示的外，他们绝不能窥测他的玄妙。他的知觉，包罗天地。天地的保管，不能使他疲倦。他确是至尊的，确是至大的。", "在每次主命拜后及睡前诵读。", "谁在每次主命拜后诵读，唯有死亡能阻止他进入天堂；睡前诵读则可获保护直至天明。"),
        "dua_before_sleep" to DuaText("睡前祈祷词", "主啊！我奉你的名而死（睡）而生（醒）。", "躺下后诵读。", "先知（愿主福安之）睡前诵读此词。"),
        "dua_sleep_tasbeeh" to DuaText("睡前法蒂玛的赞辞", "赞主超绝（三十三遍），万赞归主（三十三遍），真主至大（三十四遍）。", "睡前诵读——先知（愿主福安之）曾教导法蒂玛与阿里（愿主喜悦之）。", "先知（愿主福安之）说，这比一名仆人对你更有益。"),
        "dua_sleep_qina_adhab" to DuaText("免遭刑罚的祈祷词", "主啊！求你在你复活众仆的那日保护我免遭你的刑罚。", "右手放于面颊下诵读三遍。", "将睡眠转化为对死亡的提醒和对后世的准备。"),
        "dua_bad_dream" to DuaText("做恶梦后的祈祷词", "我求真主庇护，免遭受诅咒的恶魔的侵扰。", "做恶梦后：向左轻吐三次，然后翻身向另一侧躺。", "恶梦不会伤害你；不要将其告诉任何人。"),
        "dua_yunus" to DuaText("优努斯先知（愿主赐福之）的祈祷词", "除你外绝无应受崇拜的，你超绝万物，我确是不义的人。", "优努斯先知在鱼腹中的祈祷词——适用于任何困境。", "任何穆斯林在任何事情上诵读此词祈祷，真主必定应答他。"),
        "dua_karb" to DuaText("大难临头时的祈祷词", "除真主外绝无应受崇拜的，他是至大的、至容忍的。除真主外绝无应受崇拜的，他是宝座的主。除真主外绝无应受崇拜的，他是诸天、大地和尊严宝座的主。", "在严重困境和窘迫时诵读。", "先知（愿主福安之）在困境中诵读此词。"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("哦，永生的、维护万物的主啊", "哦，永生的、维护万物的主啊！我求你的慈悯相助。", "当事情变得十分沉重时诵读。", "每当有事让先知（愿主福安之）忧虑时，他便如此祈求。"),
        "dua_hasbunallah" to DuaText("真主使我们足够，他是最好的监护者", "真主使我们足够，他是最好的监护者。", "在惧怕敌人或面临重大危险时诵读。", "易卜拉欣（愿主赐福之）被投入火中时曾诵读此词，先知（愿主福安之）在危难中也诵读过。"),
        "dua_entering_home" to DuaText("进屋时的祈祷词", "奉真主之名。", "进屋时提及真主之名并道安。", "进屋和用餐时纪念真主的人，恶魔会说：你们没有过夜之处，也没有晚餐。"),
        "dua_travel" to DuaText("旅行（乘坐交通工具）祈祷词", "赞颂那使这交通工具为我们效劳的主超绝万物，我们本来是无法驾驭它的，我们必定要归依我们的主。", "上车后诵读三遍真主至大后诵读。", "旅途中求保护和吉庆的圣行祈祷词。"),
        "dua_entering_market" to DuaText("进入集市时的祈祷词", "除真主外绝无应受崇拜的，他是独一的，没有伙伴。主权归他，赞颂归他。他使生使死，他永生不死。一切美善都在他的掌握中，他对万事全能。", "进入集市时诵读。", "圣训提及此词有巨大的赏赐（百万件善功）。"),
        "dua_adam_forgiveness" to DuaText("阿丹先知（愿主赐福之）的祈祷词", "我们的主啊！我们确已自欺，你若不赦宥我们，不慈悯我们，我们必定成为亏损的人。", "阿丹与哈娃（愿主赐福之）的忏悔祈祷词。", "人类第一次的忏悔——真主接受了它。"),
        "dua_abu_bakr" to DuaText("教导给艾布·伯克尔（愿主喜悦之）的祈祷词", "主啊！我确已大大地自欺，除你外没有人能饶恕罪过，求你从你那里赦宥我、慈悯我；你确是至赦的、至慈的。", "先知（愿主福安之）教导艾布·伯克尔·西迪克（愿主喜悦之）在礼拜中（作证词后）诵读。", "礼拜末尾的圣行祈祷词。"),
        "dua_astaghfirullah_atubu" to DuaText("每日的求恕词", "我向真主求恕，我向他悔罪。", "先知（愿主福安之）每天求恕超过七十次。", "先知（愿主福安之）说：我每天向真主求恕并悔罪超过七十次。"),
        "dua_laylatul_qadr" to DuaText("盖德尔之夜的祈祷词", "主啊！你确是至赦的，你喜爱饶恕，求你饶恕我。", "教导给阿伊莎（愿主喜悦之）以在盖德尔夜诵读。", "斋月最后几夜及盖德尔夜的特别祈祷词。"),
        "dua_family_coolness" to DuaText("眼目的凉爽（配偶与子女）", "我们的主啊！求你使我们的配偶和后裔成为我们眼目的凉爽，求你使我们成为敬畏者的表率。", "为求得贤良配偶和子女的《古兰经》祈祷词。", "为家庭的和睦与子女的良善而祈求。"),
        "dua_righteous_children" to DuaText("求赐纯洁的后裔", "我的主啊！求你从你那里赐我纯洁的后裔，你确是听取祈祷的。", "宰凯里雅先知（愿主赐福之）的祈祷词。", "为求子嗣的《古兰经》祈祷词。"),
        "dua_ibrahim_prayer_family" to DuaText("礼拜的坚持者", "我的主啊！求你使我和我的后裔成为谨守拜功的人。我们的主啊！求你接受我的祈祷。我们的主啊！求你在清算之日饶恕我、我的父母和信士们。", "易卜拉欣先知（愿主赐福之）为自己和后裔所作的祈祷词。", "通常在礼拜末尾诵读。"),
        "dua_newlywed" to DuaText("祝贺新婚夫妇", "愿真主祝福你，愿真主赐福于你，愿真主使你们二人在美善中相聚。", "祝贺他人新婚时诵读。", "婚礼的圣行祝词。"),
        "dua_before_eating" to DuaText("用餐前的祈祷词", "奉真主之名。（若忘记：）奉真主之名，从始至终。", "用餐前诵读，若忘记，可在用餐中途补诵。", "诵念清真言使恶魔无法分享食物。"),
        "dua_after_eating" to DuaText("用餐后的祈祷词", "一切赞颂全归真主，他在我毫无能力和力量的情况下赐予我这食物。", "用餐结束后诵读。", "诵读此词者，以往的罪过将被赦免。"),
        "dua_host" to DuaText("为主人祈祷", "主啊！求你祝福他们所赐予的，求你饶恕他们，慈悯他们。", "在他人家中用餐后为主人祈祷。", "以圣行的方式感谢款待。"),
        "dua_breaking_fast" to DuaText("开斋时的祈祷词", "口渴已消，血脉已润，若真主意欲，报酬已确定。", "开斋时刻诵读。", "先知（愿主福安之）开斋时如此说。"),
        "dua_new_clothes" to DuaText("穿新衣时的祈祷词", "主啊！一切赞颂归你，是你赐我穿上此衣。我求你这衣物的美善及其所为之美善，我求你庇护我免遭这衣物的邪恶及其所为之邪恶。", "穿新衣（提及衣物名称，如衬衫或头巾）时诵读。", "先知（愿主福安之）穿新衣时如此祈祷。（每日穿衣的祈祷词见「穿衣」条目。）"),
        "dua_rabbana_atina" to DuaText("今世与后世的美善", "我们的主啊！求你在今世赐我们美善，在后世也赐我们美善，求你保护我们免遭火狱的刑罚。", "先知（愿主福安之）最常诵读的祈祷词。", "汇聚今世与后世一切美善的祈祷词。"),
        "dua_rabbi_zidni_ilma" to DuaText("求增知识", "我的主啊！求你增加我的知识。", "为增加知识而祈求。", "真主命令先知（愿主福安之）只求增加知识，此外别无他求。"),
        "dua_musa_sharh_sadr" to DuaText("敞开心胸（穆萨圣人）", "我的主啊！求你为我敞开我的心胸，求你使我的事情容易，求你解开我舌上的结，以便他们能明白我的话。", "考试、演讲或任何艰难任务之前诵读。", "穆萨先知（愿主赐福之）的祈祷词——内心的平静和工作的顺利。"),
        "dua_la_tuzigh" to DuaText("心灵的坚定", "我们的主啊！你既引导我们，求你不要使我们的心动摇，求你从你那里赐我们慈恩；你确是博施的。", "为坚守正道而祈求。", "祈求信仰坚定的祈祷词。"),
        "dua_ya_muqallib" to DuaText("哦，转变心灵者啊", "哦，转变心灵者啊！求你使我的心坚定在你的宗教上。", "先知（愿主福安之）常诵读此祈祷词。", "据乌姆·萨拉玛（愿主喜悦之）所述，这是先知（愿主福安之）最常诵读的祈祷词。"),
        "dua_la_tuakhidhna" to DuaText("黄牛章末尾两节经文", "我们的主啊！求你不要因我们遗忘或错误而惩罚我们。我们的主啊！求你不要使我们负担如你使前人负担的重任。我们的主啊！求你不要使我们负担我们不能承受的。求你饶恕我们，赦免我们，慈悯我们。你是我们的保护者，求你援助我们，抵抗不信道的民众。", "夜间睡前诵读——黄牛章末尾两节经文。", "谁在夜间诵读黄牛章末尾两节经文，那便足以使他免遭一切灾祸。"),
        "dua_visiting_sick" to DuaText("探望病人时的祈祷词", "我求伟大宝座之主、至大的真主医治你。", "探望病人时诵读七遍。", "若死期未到，真主必将医治他。"),
        "dua_ruqyah_pain" to DuaText("为身体疼痛祈祷", "我求真主及其大能庇护，免遭我所感受和所惧怕之物的邪恶。", "将手放在疼痛处，先诵三遍太斯米，再诵此词七遍。", "先知（愿主福安之）曾教导奥斯曼·本·艾比·阿斯（愿主喜悦之）以此治疗疼痛。"),
        "dua_ruqyah_nabawi" to DuaText("先知式的治病祈祷", "主啊！世人的主宰啊！求你解除病痛，赐予痊愈，你是医治者，除你的医治外别无医治；求你赐予不留后遗症的痊愈。", "探视病人时以手抚摸病处诵读。", "先知（愿主福安之）探望家中病人时如此祈祷。"),
        "dua_kalimat_tammat" to DuaText("求庇于真主完美的言辞", "我求庇于真主完美的言辞，免遭他所创造之物的邪恶。", "停留某地或在傍晚时诵读。", "谁在某地停留并诵读此词，在他离开之前任何东西都不会伤害他。"),
        "dua_evil_eye" to DuaText("保护孩子免遭邪视", "我求真主完美的言辞保护你们二人，免遭一切恶魔、一切毒物和一切邪恶眼目的伤害。", "先知（愿主福安之）曾为哈桑与侯赛因（愿主喜悦之）诵读此词。", "保护孩子免遭邪视和伤害的圣行祈祷词（若只有一个孩子，说「我求庇护你」）。"),
        "dua_seeing_afflicted" to DuaText("看到他人受苦时", "一切赞颂全归真主，他使我免遭他考验你的那些事，并且使我胜过他所创造的许多众生。", "看到他人受考验时（在心中默诵）。", "诵读此词者将免遭那种考验。"),
        "dua_istikhara" to DuaText("择善拜（伊斯提卡拉）", "主啊！我凭借你的知识求得美善，凭借你的大能求得力量，我向你祈求你伟大的恩惠。你全能而我无能，你全知而我无知，你是深知幽玄的。主啊！你若知道这件事（心中默想此事）对我的宗教、生活和结局是美善的，求你为我注定它，使它容易，并为我祝福它；你若知道这件事对我的宗教、生活和结局是不善的，求你使它远离我，使我远离它，无论美善在何处，求你为我注定它，然后使我为此满足。", "在合法事务中礼两拜副功拜后诵读，以求最好的结果。", "先知（愿主福安之）教导弟子们在一切事务中的择善拜，如同教导他们一部《古兰经》章节一样。"),
        "dua_allahumma_bika_asbahna" to DuaText("主啊，我们靠你进入清晨", "主啊！我们靠你进入清晨，靠你进入黄昏；靠你而生，靠你而死，复活也归于你。", "清晨诵读。", "先知（愿主福安之）教导弟子们早晚诵读此词。"),
        "dua_allahumma_bika_amsayna" to DuaText("主啊，我们靠你进入黄昏", "主啊！我们靠你进入黄昏，靠你进入清晨；靠你而生，靠你而死，归宿也归于你。", "傍晚诵读。", "先知（愿主福安之）教导弟子们早晚诵读此词。"),
        "dua_afiyah_morning" to DuaText("祈求平安", "主啊！我求你赐我今世与后世的宽恕与平安。", "先知（愿主福安之）无论早晚都从未间断此祈祷。", "没有人被赐予比平安更好的东西。"),
        "dua_afini_fi_badani" to DuaText("身体、听觉与视觉的健康", "主啊！求你使我的身体健康。主啊！求你使我的听觉健康。主啊！求你使我的视觉健康。除你外绝无应受崇拜的。", "每天早晚各诵读三遍。", "为健康和感官的保护而祈求。"),
        "dua_ya_hayyu_aslih" to DuaText("整顿我一切事务", "哦，永生的、维护万物的主啊！我凭借你的慈悯求助：求你整顿我一切的事务，求你不要将我托付给自己，哪怕是一眨眼的功夫。", "先知（愿主福安之）曾嘱咐法蒂玛（愿主喜悦之）早晚诵读。", "在一切事务中祈求真主的帮助。"),
        "dua_subhanallah_adada_khalqihi" to DuaText("祝威莱（愿主喜悦之）的赞辞", "赞主超绝，万赞归主——如其所造之物之数，如其所喜悦之量，等同于他宝座之重，及其言辞之墨。", "清晨诵读三遍——比数小时的记主更为厚重。", "这四句话诵读三遍，其分量超过从黎明到上午的记主。"),
        "dua_salawat" to DuaText("易卜拉欣式的迪罗德（求主福安）", "主啊！求你祝福穆罕默德及其家属，犹如你祝福易卜拉欣及其家属一样；你确是可颂的、荣耀的。主啊！求你福佑穆罕默德及其家属，犹如你福佑易卜拉欣及其家属一样；你确是可颂的、荣耀的。", "在礼拜中及任何时候为先知（愿主福安之）祈福。", "谁为先知祈福一次，真主便为他降下十次慈悯（穆斯林圣训408）。"),
        "dua_wudu_after" to DuaText("小净后的祈祷词", "我作证，除真主外绝无应受崇拜的，他是独一的，没有伙伴；我又作证，穆罕默德（愿主福安之）是他的仆人和使者。主啊！求你使我成为悔罪者和自净者之一。", "完成小净后诵读。", "天堂的八道门将为他敞开，他可随意从任何一道进入。"),
        "dua_wudu_before" to DuaText("小净前的祈祷词", "奉真主之名。", "开始小净时诵读。", "凡不提及真主之名而做小净者，其小净是不完整的。"),
        "dua_istiftah" to DuaText("礼拜开头的祈祷词（赞词）", "主啊！赞你超绝，赞颂全归你，你的名号是吉祥的，你的尊严是崇高的，除你外绝无应受崇拜的。", "礼拜开始，在开端大赞词之后立即诵读。", "礼拜开头的圣行祈祷词。"),
        "dua_ruku" to DuaText("鞠躬时的赞辞", "赞我至大的主超绝。", "鞠躬时至少诵读三遍。", "鞠躬时的圣行赞辞。"),
        "dua_sujood" to DuaText("叩头时的赞辞", "赞我至高的主超绝。", "叩头时至少诵读三遍。", "仆人在叩头时最接近他的主（穆斯林圣训482）。"),
        "dua_rising_ruku" to DuaText("鞠躬起身时的赞辞", "真主听取赞颂他的人。我们的主啊！一切赞颂全归你。", "从鞠躬中起身并站直时诵读。", "谁诵读「我们的主啊，赞颂全归你」恰与天使的诵读相合，其以往的罪过将被赦免。"),
        "dua_between_sajdas" to DuaText("两次叩头之间的祈祷词", "我的主啊！求你饶恕我。我的主啊！求你饶恕我。", "坐在两次叩头之间时诵读。", "两次叩头之间坐姿的圣行祈祷词。"),
        "dua_before_salam_four" to DuaText("道安前求庇免遭四事", "主啊！我求你庇护，免遭火狱的刑罚，免遭坟墓的刑罚，免遭生死的考验，免遭假麦西哈（达贾勒）的邪恶考验。", "最后的作证词和求主福安之后、道安之前诵读。", "先知（愿主福安之）命令人们求庇免遭这四件事。"),
        "dua_qunoot_witr" to DuaText("威特尔拜中的库努特", "主啊！求你使我列于你所引导的人之中，求你使我列于你所赐平安的人之中，求你眷顾我如你眷顾他人一样，求你在你所赐予的事物中祝福我，求你保护我免遭你所注定的邪恶。你判决而无人能对你判决，你所亲近的人绝不会受辱。我们的主啊，你是吉祥的、崇高的。", "在威特尔拜中诵读——先知（愿主福安之）教导哈桑·本·阿里（愿主喜悦之）。", "威特尔拜的圣行库努特。（哈乃斐学派也常用「主啊，我们求你相助」一词。）"),
        "dua_qunoot_hanafi" to DuaText("库努特（主啊，我们求你相助）", "主啊！我们求你相助，求你饶恕，我们信仰你，依赖你，以最好的方式赞美你，我们感谢你而不忘恩，我们摒弃一切违抗你的人。主啊！我们只崇拜你，我们只为你礼拜叩头，我们只为你奔走效力，我们企望你的慈悯，惧怕你的刑罚；你的刑罚必将降临不信道者。", "威特尔拜中诵读——哈乃斐学派的做法。", "据传自欧麦尔（愿主喜悦之）的库努特。"),
        "dua_sleep_aslamtu" to DuaText("睡前的最后话语", "主啊！我已归顺于你，将我的事情托付于你，将我的背靠于你的庇护，出于对你的希望和敬畏。除你之外，没有可逃避与投靠之处。我信仰你所降示的经典，信仰你所派遣的先知。", "小净后向右侧躺下——睡前的最后话语。", "若他当晚死去，他便死在天性（伊斯兰）之上。"),
        "dua_waking_night" to DuaText("夜间醒来时的祈祷词", "除真主外绝无应受崇拜的，他是独一的，没有伙伴。主权归他，赞颂归他，他对万事全能。一切赞颂全归真主，赞主超绝，除真主外绝无应受崇拜的，真主至大，除真主外绝无能力和力量。主啊，求你饶恕我。", "夜间醒来时诵读。", "他的祈祷将得到应答，若他起来做小净并礼拜，他的礼拜将被接受。"),
        "dua_hamm_ibn_masud" to DuaText("忧愁时的祈祷（伊本·迈斯欧德）", "主啊！我是你的仆人，你仆人之子，你婢女之子。我的额发在你手中，你对我的判决必将执行，你对我的裁定是公正的。我以你自己所命名、或在你的经典中所启示、或曾教给你任何一个被造物、或只有你自己保留在幽玄知识中的每一个属于你的名号，恳求你使《古兰经》成为我心灵的甘泉、我胸怀的光明、我忧愁的解除和我烦恼的消散。", "在忧愁与困苦时诵读——真主以喜悦取代忧愁。", "真主为他解除烦恼与忧愁，并以喜悦取而代之。"),
        "dua_difficulty_sahl" to DuaText("事情困难时的祈祷词", "主啊！除你使之容易者外，没有什么是容易的；你若意欲，能使困难变得容易。", "感到事情困难时诵读。", "有助于考试和艰难任务的顺利完成。"),
        "dua_musibah" to DuaText("遭遇灾难时的祈祷词（伊斯提尔贾）", "我们确属于真主，我们必将归于他。主啊！求你以我的灾难赏赐我，求你以更好的事物取代它。", "遭遇任何损失或灾难时诵读。", "真主必以更好的事物取而代之——乌姆·萨拉玛（愿主喜悦之）便因此获得了先知（愿主福安之）。"),
        "dua_debt" to DuaText("求解脱债务", "主啊！求你以你所准许的使我免于你所禁止的，求你以你的恩惠使我不再仰赖你以外的任何人。", "为偿还债务而祈祷——阿里（愿主喜悦之）所传授。", "即便债务如山那样重，真主也必为他偿清。"),
        "dua_anger" to DuaText("愤怒时的祈祷词", "我求真主庇护，免遭受诅咒的恶魔的侵扰。", "愤怒时诵读。", "先知（愿主福安之）说：若他诵读此词，他的怒气便会消散。"),
        "dua_waswasa" to DuaText("对抗信仰中的邪念", "我信仰真主和他的众使者。", "当有关于信仰的邪念侵扰时诵读。", "当邪念来临时，诵读此词并停止思考（同时求真主庇护）。"),
        "dua_travel_full" to DuaText("完整的旅行祈祷词", "主啊！我们在这次旅行中求你赐予善行与敬畏，求你赐予令你喜悦的行为。主啊！求你使这次旅程对我们容易，缩短其路程。主啊！你是旅途的同伴，是家人的守护者。", "启程时，在「赞主超绝，他使其为我们服务」之后诵读。", "完整的圣行旅行祈祷词。"),
        "dua_return_travel" to DuaText("旅行归来时的祈祷词", "我们归来了，悔罪了，敬拜了，赞颂我们的主。", "旅行归来时诵读。", "先知（愿主福安之）旅行归来时如此诵读。"),
        "dua_farewell_traveller" to DuaText("为远行者送行", "我将你的宗教、你的信托和你行为的结局托付给真主。", "为远行者送行时诵读。", "托付给真主的东西永不会丢失。"),
        "dua_entering_town" to DuaText("停留某地时的祈祷词", "我求庇于真主完美的言辞，免遭他所创造一切的邪恶。", "在某地停留或抵达新城镇时诵读。", "在他离开之前，任何东西都不会伤害他。"),
        "dua_boarding_ship" to DuaText("登船（乘坐交通工具）时的祈祷词", "奉真主之名，其航行与停泊皆奉真主之名；我的主确是至赦的、至慈的。", "登船或乘坐交通工具时诵读——努哈先知（愿主赐福之）的话语。", "《古兰经》经文——努哈（愿主赐福之）方舟的祈祷词。"),
        "dua_istighfar_hayyul_qayyum" to DuaText("向永生维护万物的主求恕", "我向真主求恕，除他外绝无应受崇拜的，他是永生的、维护万物的，我向他悔罪。", "为悔罪而诵读。", "即便他曾在战场上逃跑，他的罪过也会被赦免。"),
        "dua_rabbighfir_warham" to DuaText("我的主啊，求你饶恕和慈悯", "我的主啊！求你饶恕和慈悯，你是最好的慈悯者。", "《古兰经》祈祷词——求饶恕与慈悯。", "信士章的末尾一节经文。"),
        "dua_majlis_kaffarah" to DuaText("聚会的赎罪辞", "主啊，赞你超绝，赞颂归你；我作证除你外绝无应受崇拜的，我求你饶恕，我向你悔罪。", "离开聚会时诵读。", "这成为对聚会中所说过错的一种赎罪。"),
        "dua_jami_forgiveness" to DuaText("全面的求恕祈祷词", "主啊！求你饶恕我的过失、我的无知、我在事务中的过度，以及一切你比我更了解的事情。", "先知（愿主福安之）的一段全面祈祷词。", "先知（愿主福安之）常如此祈祷。"),
        "dua_parents_nuh" to DuaText("努哈先知为父母所作的祈祷", "我的主啊！求你饶恕我、我的父母、凡以信士身份进入我家门的人，以及所有的信士男女。", "为父母和信士们祈祷。", "努哈先知（愿主赐福之）的祈祷词。"),
        "dua_shukr_parents" to DuaText("感谢父母与求良善后裔", "我的主啊！求你启发我感谢你所赐予我和我父母的恩典，并使我做你所喜悦的善功，求你使我的后裔良善。我向你悔罪，我是归顺者之一。", "四十岁时诵读的《古兰经》祈祷词。", "感恩、善功与子女的良善——尽在一段祈祷词中。"),
        "dua_intimacy" to DuaText("夫妻同房前的祈祷词", "奉真主之名。主啊！求你使恶魔远离我们，求你使恶魔远离你所赐予我们的（子女）。", "夫妻同房前诵读。", "若真主注定有子女，恶魔将永不能伤害他。"),
        "dua_ibrahim_children_protection" to DuaText("求庇护家园与子女", "我的主啊！求你使这座城市平安，求你使我和我的子孙远离拜偶像。", "易卜拉欣先知（愿主赐福之）的祈祷词——求城市与子女的平安。", "坚守认主独一的祈祷词。"),
        "dua_drinking_milk" to DuaText("饮用牛奶时的祈祷词", "主啊！求你为我们祝福它，求你赐予我们更多。", "饮用牛奶时诵读。", "牛奶既可作食物，也可作饮品，足以令人满足。"),
        "dua_iftar_host" to DuaText("在他人家中开斋时", "愿封斋者在你这里开斋，愿善良之人享用你的食物，愿天使为你祈祷。", "在他人家中开斋时诵读。", "先知（愿主福安之）为主人所作的祈祷词。"),
        "dua_seeing_first_fruit" to DuaText("看到当季初熟果实时", "主啊！求你祝福我们的果实，求你祝福我们的城市，求你祝福我们的撒阿和穆德（度量单位）。", "看到当季第一批果实时诵读。", "为给养和城市的吉庆而祈求的祈祷词。"),
        "dua_good_news" to DuaText("收到好消息时", "一切赞颂全归真主，因他的恩惠，美好的事情得以圆满完成。", "收到好消息时诵读（并行感恩叩头）。", "先知（愿主福安之）看到令他喜悦之事时如此说。"),
        "dua_looking_mirror" to DuaText("照镜子时的祈祷词", "主啊！你既使我的容貌美好，求你也使我的品德美好。", "照镜子时诵读。", "先知（愿主福安之）如此祈祷（即使不提及镜子，这段祈祷词也已确立）。"),
        "dua_rabbana_taqabbal" to DuaText("求主接受善功", "我们的主啊！求你接受我们的（善功），你确是全聪的、全知的。求你接受我们的悔罪，你确是至赦的、至慈的。", "易卜拉欣与伊斯玛仪（愿主赐福之）建造天房时所作的祈求。", "每做一件善功之后祈求其被接受的祈祷词。"),
    )
}
